def proposed_pr(
    pr_id: str,
    wp: str,
    title: str,
    repo: str,
    objective: str,
    *,
    deps: list[str] | None = None,
    gate: str = "A1",
    size: str = "Medium",
    files: list[str] | None = None,
    scope: list[str] | None = None,
    non_goals: list[str] | None = None,
    changes: dict[str, str] | None = None,
    tests: list[str] | None = None,
    blocked_by: list[str] | None = None,
    sources: list[str] | None = None,
    dri: str = "Alan",
    implementer: str = "Alan",
    reviewer: str = "Luke",
    approver: str = "Luke",
    expertise: list[str] | None = None,
    high_review: bool = False,
    readiness: str = "Dependencies unmet",
) -> dict[str, Any]:
    return {
        "id": pr_id,
        "wp": wp,
        "title": title,
        "repo": repo,
        "base": "main",
        "objective": objective,
        "deps": deps or [],
        "gate": gate,
        "size": size,
        "files": files or [],
        "scope": scope or [],
        "non_goals": non_goals or [],
        "changes": changes or {},
        "tests": tests or [],
        "blocked_by": blocked_by or [],
        "sources": sources or [],
        "dri": dri,
        "implementer": implementer,
        "reviewer": reviewer,
        "approver": approver,
        "expertise": expertise or ["Python/FastAPI", "PostgreSQL", "security-aware product engineering"],
        "high_review": high_review,
        "readiness": readiness,
        "project_item": f"{PROJECT_URL}?query={pr_id}",
    }


