PR_BY_ID = {pr["id"]: pr for pr in PROPOSED_PRS}


def plan_filename(wp_id: str) -> str:
    wp = WP_BY_ID[wp_id]
    return f"{wp['number']:02d}-{wp['slug']}.md"


