def transition(
    start: str,
    end: str,
    actor: str,
    evidence: str,
    key: str,
    invalid: str,
    audit: str,
    retry: str,
    recovery: str,
) -> dict[str, str]:
    return {"start": start, "end": end, "actor": actor, "evidence": evidence, "key": key, "invalid": invalid, "audit": audit, "retry": retry, "recovery": recovery}


